/*!
 * figlet.js - JavaScript implementation of FIGlet
 * https://github.com/patorjk/figlet.js
 * Version 1.5.2
 * License: MIT
 */
(function () {
  var figlet = {
    fonts: {},
    parseFont: function (name, fontData) {
      var lines = fontData.split("\n");
      var header = lines[0].split(" ");
      var hardblank = header[0].charAt(header[0].length - 1);
      var height = parseInt(header[1]);
      var commentLines = parseInt(header[5]);
      var charData = {};
      lines.splice(0, 1 + commentLines);
      var currentChar = 32;
      var i = 0;
      while (i < lines.length) {
        var charLines = lines.slice(i, i + height);
        i += height;
        charData[currentChar] = charLines.map(function (line) {
          return line
            .replace(RegExp("\\" + hardblank, "g"), " ") // ubah hardblank ke spasi
            .replace(/@+\s*$/g, "") // hapus semua @ dan spasi di akhir baris
            .replace(/@/g, " "); // ubah semua @ tersisa jadi spasi
        });

        currentChar++;
      }
      figlet.fonts[name] = charData;
    },
    text: function (txt, opt, cb) {
      if (typeof opt == "function") {
        cb = opt;
        opt = {};
      }
      opt = opt || {};
      var fontName = opt.font || "Standard";
      var fontData = figlet.fonts[fontName];
      if (!fontData) {
        return cb(new Error("Font not loaded: " + fontName));
      }
      var out = "";
      var height = fontData[32].length;
      for (var h = 0; h < height; h++) {
        for (var i = 0; i < txt.length; i++) {
          var ch = txt.charCodeAt(i);
          if (!fontData[ch]) ch = 63;
          out += fontData[ch][h];
        }
        out += "\n";
      }
      cb(null, out);
    },
    loadFont: function (name, path, cb) {
      if (typeof path == "function") {
        cb = path;
        path = null;
      }
      if (figlet.fonts[name]) return cb(null);
      var xhr = new XMLHttpRequest();
      xhr.open("GET", path || "./fonts/" + name + ".flf", true);
      xhr.onreadystatechange = function () {
        if (xhr.readyState === 4) {
          if (xhr.status === 200 || xhr.status === 0) {
            figlet.parseFont(name, xhr.responseText);
            cb(null);
          } else {
            cb(new Error("Font load failed: " + name));
          }
        }
      };
      xhr.send();
    },
  };
  if (typeof module !== "undefined" && module.exports) {
    module.exports = figlet;
  } else {
    window.figlet = figlet;
  }
})();
